// ==============================================================================
// Antigravity <-> Gemini Web Bridge: Background Service Worker (Manifest V3)
// Tab monitoring, lifecycle management, badge updates
// ==============================================================================

chrome.runtime.onInstalled.addListener(() => {
    console.log('[Antigravity Bridge] Extension installed successfully.');
});

// Helper: Find active or any open Gemini tab
async function findGeminiTab() {
    const tabs = await chrome.tabs.query({ url: '*://gemini.google.com/*' });
    return tabs && tabs.length > 0 ? tabs[0] : null;
}

// Listen for messages from popup or other extension parts
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
    if (request.action === 'GET_STATUS') {
        findGeminiTab().then(tab => {
            sendResponse({
                hasGeminiTab: Boolean(tab),
                tabId: tab ? tab.id : null,
                tabUrl: tab ? tab.url : null
            });
        });
        return true; // async sendResponse
    }

    if (request.action === 'OPEN_GEMINI') {
        findGeminiTab().then(tab => {
            if (tab) {
                chrome.tabs.update(tab.id, { active: true });
                chrome.windows.update(tab.windowId, { focused: true });
            } else {
                chrome.tabs.create({ url: 'https://gemini.google.com/app', active: true });
            }
        sendResponse({ success: true });
        return true;
    }

    if (request.action === 'RELOAD_TAB') {
        findGeminiTab().then(tab => {
            if (tab) {
                chrome.tabs.reload(tab.id);
                sendResponse({ success: true });
            } else {
                sendResponse({ success: false, error: 'No Gemini tab found' });
            }
        });
        return true;
    }

    if (request.action === 'RELOAD_EXTENSION') {
        chrome.runtime.reload();
        sendResponse({ success: true });
        return true;
    }
});

